import{_ as l,o as s,c as o,ag as r}from"./chunks/framework.D2veAa-g.js";const p=JSON.parse('{"title":"章节练习 错题集","description":"","frontmatter":{"title":"章节练习 错题集"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/章节练习 错题集.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/章节练习 错题集.md","lastUpdated":null}'),a={name:"架构师 在线刷题/51CT0题库 章节练习/章节练习 错题集.md"};function n(i,t,g,e,c,d){return s(),o("div",null,[...t[0]||(t[0]=[r('<h2 id="q4-某企业要开发一个具有较强用户交互功能的应用程序-最适合采用的架构风格是-。" tabindex="-1">Q4. 某企业要开发一个具有较强用户交互功能的应用程序，最适合采用的架构风格是（ ）。 <a class="header-anchor" href="#q4-某企业要开发一个具有较强用户交互功能的应用程序-最适合采用的架构风格是-。" aria-label="Permalink to &quot;Q4. 某企业要开发一个具有较强用户交互功能的应用程序，最适合采用的架构风格是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> SOA风格</li><li><strong>B.</strong> 虚拟机风格</li><li><strong>C.</strong> MVC风格</li><li><strong>D.</strong> 平台/插件风格</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>A：SOA风格主要用于企业集成<br> B：错误，虚拟机风格用于解释器或专家系统<br> C：正确，MVC风格专门用于用户交互程序的设计<br> D：错误，平台/插件风格主要用于具有插件扩展功能的应用程序</p><p>【教材依据】MVC风格用于用户交互程序的设计。因此本题的正确答案是C。</p><ul><li><strong>SOA 风格</strong>：面向服务，适用于企业系统集成、跨系统调用。</li><li><strong>虚拟机风格</strong>：基于解释器、规则系统，适合规则引擎、脚本语言环境。</li><li><strong>MVC 风格</strong>：明确将交互系统分为 <strong>模型（Model）</strong>、<strong>视图（View）</strong>、<strong>控制器（Controller）</strong>，专为<strong>用户交互频繁、界面多变</strong>的应用设计。</li><li><strong>平台/插件风格</strong>：核心系统 + 插件式扩展，适合 IDE、浏览器等。</li></ul></div></details><hr><h2 id="q5-某系统需要将整个处理过程分解为多个独立的处理步骤-最适合采用的架构风格是-。" tabindex="-1">Q5. 某系统需要将整个处理过程分解为多个独立的处理步骤，最适合采用的架构风格是（ ）。 <a class="header-anchor" href="#q5-某系统需要将整个处理过程分解为多个独立的处理步骤-最适合采用的架构风格是-。" aria-label="Permalink to &quot;Q5. 某系统需要将整个处理过程分解为多个独立的处理步骤，最适合采用的架构风格是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> MVC风格</li><li><strong>B.</strong> 管道-过滤器风格</li><li><strong>C.</strong> C/S风格</li><li><strong>D.</strong> 虚拟机风格</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><ul><li><strong>A. MVC风格</strong>：适用于用户交互界面，模型-视图-控制器分离，与“处理步骤分解”无关。</li><li><strong>C. C/S风格</strong>：客户端-服务器架构，关注的是分布式部署和请求/响应，不强调处理链路分解。</li><li><strong>D. 虚拟机风格</strong>：适用于解释执行自定义规则或脚本，如解释器、规则引擎，与“步骤分解”不直接匹配</li></ul><p><strong>依赖的是数据</strong>（前一个的输出），但<strong>过滤器本身是独立运行的组件</strong>。这正是管道-过滤器的核心特征</p><ul><li><strong>管道-过滤器风格</strong>： <ul><li>每个<strong>处理步骤</strong>就是一个<strong>过滤器</strong>（Filter）。</li><li>步骤之间通过<strong>管道</strong>（Pipe）连接，前一个步骤的输出作为后一个步骤的输入。</li><li>每个过滤器都是<strong>独立</strong>的组件，可以单独开发、修改、复用。</li><li>经典实例：传统编译器（词法分析 → 语法分析 → 语义分析 → 代码生成）、Linux 命令管道（<code>ps -ef | grep java</code>）。</li></ul></li></ul><p>尽量管道过滤器是依赖前一个步骤的输入，但是他自身的逻辑是独立的。<strong>依赖的是数据，而不是实现</strong>。</p><p><strong>依赖的是数据</strong>（前一个的输出），但<strong>过滤器本身是独立运行的组件</strong>。这正是管道-过滤器的核心特征，而不是它的矛盾点。</p></div></details><hr><h2 id="q7-下列关于软件架构建模方法的描述-错误的是-。" tabindex="-1">Q7. 下列关于软件架构建模方法的描述，错误的是（）。 <a class="header-anchor" href="#q7-下列关于软件架构建模方法的描述-错误的是-。" aria-label="Permalink to &quot;Q7. 下列关于软件架构建模方法的描述，错误的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 动态模型主要研究系统的重新配置或演化等&quot;大颗粒&quot;行为</li><li><strong>B.</strong> 框架模型比结构模型更侧重描述结构的细节</li><li><strong>C.</strong> 过程模型主要研究构造系统的步骤和过程</li><li><strong>D.</strong> 这四种模型需要有机结合才能完整描述软件架构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><ul><li><strong>A. 正确。</strong> 动态模型确实关注系统运行时的大颗粒行为，如重新配置、演化、通信等，而不是细颗粒的函数调用。</li><li><strong>B. 错误。</strong> 框架模型（Framework Model）通常是从宏观层面定义系统的结构、协作关系或“骨架”，它的<strong>抽象层次更高</strong>，反而<strong>不侧重描述结构的细节</strong>。描述结构细节通常是<strong>结构模型</strong>或详细设计的工作。因此“框架模型比结构模型更侧重细节”这一说法与架构分层的基本原则相悖。</li><li><strong>C. 正确。</strong> 过程模型关注构建系统的步骤、阶段、流程等。</li><li><strong>D. 正确。</strong> 四种模型（结构、框架、动态、过程）是从不同视角描述软件架构，需要有机结合才能完整表达。</li></ul><p><strong>一句话总结：</strong></p><p>框架模型是“骨架”，侧重宏观抽象；结构模型侧重具体组成与细节。<strong>B选项把关系说反了</strong>，所以是错误的。</p></div></details><hr><h2 id="q8-某项目需要重点描述系统的构件、连接件等细节结构-应选择的建模方法是-。" tabindex="-1">Q8. 某项目需要重点描述系统的构件、连接件等细节结构，应选择的建模方法是（）。 <a class="header-anchor" href="#q8-某项目需要重点描述系统的构件、连接件等细节结构-应选择的建模方法是-。" aria-label="Permalink to &quot;Q8. 某项目需要重点描述系统的构件、连接件等细节结构，应选择的建模方法是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 框架模型</li><li><strong>B.</strong> 结构模型</li><li><strong>C.</strong> 动态模型</li><li><strong>D.</strong> 过程模型</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>“模型结构”属于<strong>软件架构建模方法</strong>中的内容。在软件架构文档中，通常用四种不同的模型从不同视角来描述一个软件架构：</p><table tabindex="0"><thead><tr><th>模型类型</th><th>核心关注点</th><th>包含的关键元素</th></tr></thead><tbody><tr><td><strong>结构模型</strong></td><td><strong>静态组成</strong></td><td>构件、连接件、接口、配置、拓扑结构</td></tr><tr><td><strong>框架模型</strong></td><td><strong>宏观骨架</strong></td><td>整体结构、子系统划分、层次、协作关系</td></tr><tr><td><strong>动态模型</strong></td><td><strong>运行时行为</strong></td><td>状态变化、交互序列、并发、事件、系统演化</td></tr><tr><td><strong>过程模型</strong></td><td><strong>构建过程</strong></td><td>开发步骤、阶段划分、依赖关系</td></tr></tbody></table></div></details><hr><h2 id="q9-架构风格用于gui软件开发-用以构建灵活和可扩展的应用系统等。" tabindex="-1">Q9. （）架构风格用于GUI软件开发，用以构建灵活和可扩展的应用系统等。 <a class="header-anchor" href="#q9-架构风格用于gui软件开发-用以构建灵活和可扩展的应用系统等。" aria-label="Permalink to &quot;Q9. （）架构风格用于GUI软件开发，用以构建灵活和可扩展的应用系统等。&quot;">​</a></h2><ul><li><strong>A.</strong> 管道-过滤器风格</li><li><strong>B.</strong> MVC风格</li><li><strong>C.</strong> SOA风格</li><li><strong>D.</strong> C2风格</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>C2风格用于GU软件开发，用以构建灵活和可扩展的应用系统等。</p></div></details><hr><h2 id="q10-下面不属于微服务架构的三种实现模式之一的是-。" tabindex="-1">Q10. 下面不属于微服务架构的三种实现模式之一的是（）。 <a class="header-anchor" href="#q10-下面不属于微服务架构的三种实现模式之一的是-。" aria-label="Permalink to &quot;Q10. 下面不属于微服务架构的三种实现模式之一的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> RESTful API模式</li><li><strong>B.</strong> RESTful应用模式</li><li><strong>C.</strong> 集中消息模式</li><li><strong>D.</strong> 分布式消息模式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>挺迷的一道题目</p></div></details><hr><h2 id="q13-在云架构中-负责管理用户请求和会话控制-sessions-并决定将请求分配给哪一个处理单元的组件是-。" tabindex="-1">Q13. 在云架构中，负责管理用户请求和会话控制（sessions），并决定将请求分配给哪一个处理单元的组件是（ ）。 <a class="header-anchor" href="#q13-在云架构中-负责管理用户请求和会话控制-sessions-并决定将请求分配给哪一个处理单元的组件是-。" aria-label="Permalink to &quot;Q13. 在云架构中，负责管理用户请求和会话控制（sessions），并决定将请求分配给哪一个处理单元的组件是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 数据中间件</li><li><strong>B.</strong> 消息中间件</li><li><strong>C.</strong> 处理中间件</li><li><strong>D.</strong> 部署中间件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>这个题目也很迷，第一反应选择 C<br> 解析<br> A.数据中间件负责将数据复制到每一个处理单元，实现数据同步，不符合题目描述。<br> B.消息中间件负责管理用户请求和会话控制，并决定将请求分配给哪一个处理单元，符合题目描述。<br> C.处理中间件负责协调不同类型的处理单元，不符合题目描述。<br> D.部署中间件负责处理单元的启动和关闭，以及负载监控，不符合题目描述。因此，正确答案是B.消息中间件。</p></div></details><hr><h2 id="q16-微服务架构的实现模式中-哪种模式通常用于企业内部-背后是一个多功能的应用程序-。" tabindex="-1">Q16. 微服务架构的实现模式中，哪种模式通常用于企业内部，背后是一个多功能的应用程序（ ）。 <a class="header-anchor" href="#q16-微服务架构的实现模式中-哪种模式通常用于企业内部-背后是一个多功能的应用程序-。" aria-label="Permalink to &quot;Q16. 微服务架构的实现模式中，哪种模式通常用于企业内部，背后是一个多功能的应用程序（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> RESTful API模式</li><li><strong>B.</strong> RESTful应用模式</li><li><strong>C.</strong> 集中消息模式</li><li><strong>D.</strong> 分布式消息模式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>解析</p><p>A.RESTful API模式：这种模式通过API提供服务，常见于云服务，不符合题目描述。<br> B.RESTful应用模式：正确。这种模式通过传统的网络协议或应用协议提供服务，背后通常是一个多功能的应用程序，常见于企业内部，符合题目描述。<br> C.集中消息模式：这种模式采用消息代理实现消息队列、负载均衡等功能，不符合题目描述的特征。<br> D.分布式消息模式：这个选项在给定的微服务架构实现模式中并未提及，是一个干扰项。因此，正确答案是B.RESTful应用模式。</p><p>看起来这道题目，是直接先排除了微服务和对外提供服务的选项，然后选了一个大而全的所谓企业系统内部的应用。</p><p>在部分教材的分类中：</p><ul><li><strong>RESTful API模式</strong>：强调对外暴露服务，是“平台”或“能力开放”</li><li><strong>RESTful应用模式</strong>：强调一个完整的应用程序，内部按RESTful风格组织，适合企业内部的业务系统（如ERP、CRM的一个模块）</li></ul></div></details><hr><h2 id="q4-根据组织划分方法-下列哪个不属于架构师的5大类-。" tabindex="-1">Q4. 根据组织划分方法，下列哪个不属于架构师的5大类（ ）。 <a class="header-anchor" href="#q4-根据组织划分方法-下列哪个不属于架构师的5大类-。" aria-label="Permalink to &quot;Q4. 根据组织划分方法，下列哪个不属于架构师的5大类（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 业务架构师</li><li><strong>B.</strong> 主题领域架构师</li><li><strong>C.</strong> 解决方案架构师</li><li><strong>D.</strong> 项目架构师</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>解析<br> A：正确，属于组织划分的5大类之一<br> B:正确，属于组织划分的5大类之一<br> C:错误，解决方案架构师属于微软公司的分类方法<br> D:正确，属于组织划分的5大类之一<br> 【教材依据】从组织上划分，架构师通常可分为以下5大类：业务架构师、主题领域架构师、技术架构师、项目架构师、系统架构师。</p></div></details><hr><h2 id="q6-根据微软公司的架构师分类方法-下列属于其4大类架构师的是-。" tabindex="-1">Q6. 根据微软公司的架构师分类方法，下列属于其4大类架构师的是（ ）。 <a class="header-anchor" href="#q6-根据微软公司的架构师分类方法-下列属于其4大类架构师的是-。" aria-label="Permalink to &quot;Q6. 根据微软公司的架构师分类方法，下列属于其4大类架构师的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 主题领域架构师（Domain Architect）</li><li><strong>B.</strong> 企业架构师（Enterprise Architect）</li><li><strong>C.</strong> 业务架构师（Business Architect）</li><li><strong>D.</strong> 系统架构师（System Architecture）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>解析：</p><p>A：错误，属于组织划分的分类方法<br> B：正确，企业架构师(E)是微软分类方法中的一类<br> C：错误，属于组织划分的分类方法<br> D：错误，属于组织划分的分类方法</p><p>【教材依据】参考微软公司对架构设计师的4大类：企业架构师EA、基础结构架构师A、特定技术架构师TSA、解决方案架构师SA。</p></div></details><hr><h2 id="q3-下列不属于架构设计师6种角色特质的是-。" tabindex="-1">Q3. 下列不属于架构设计师6种角色特质的是（ ）。 <a class="header-anchor" href="#q3-下列不属于架构设计师6种角色特质的是-。" aria-label="Permalink to &quot;Q3. 下列不属于架构设计师6种角色特质的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 沟通专家</li><li><strong>B.</strong> 项目经理</li><li><strong>C.</strong> 企业家</li><li><strong>D.</strong> 系统综合者</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p><strong>解析</strong>：<br> A：错误，沟通专家是架构设计师的角色特质之一<br> B：正确，项目经理不属于架构设计师的6种角色特质<br> C：错误，企业家是架构设计师的角色特质之一<br> D：错误，系统综合者是架构设计师的角色特质之一 【教材依据】6种角色特质：包括沟通专家、领导者、战略技术专家、开发者、企业家和系统综合者</p></div></details><hr><h2 id="q2-某计算机系统输入-输出采用双缓冲工作方式-其工作过程如下图所示" tabindex="-1">Q2. 某计算机系统输入/输出采用双缓冲工作方式，其工作过程如下图所示， <a class="header-anchor" href="#q2-某计算机系统输入-输出采用双缓冲工作方式-其工作过程如下图所示" aria-label="Permalink to &quot;Q2. 某计算机系统输入/输出采用双缓冲工作方式，其工作过程如下图所示，&quot;">​</a></h2><p>假设磁盘块与缓冲区大小相同，每个盘块读入缓冲区的时间T为10μs，缓冲区送用户区的时间M为6μs，系统对每个磁盘块数据的处理时间C为2μs。若用户需要将大小为10个磁盘块的Docl文件逐块从磁盘读入缓冲区，并送用户区进行处理，那么采用双缓冲需要花费的时间<strong>为（请作答此空）μs</strong>，</p><p>比使用单缓冲节约了（ ）μs时间。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260512165112.png" alt="image.png"></p><ul><li><strong>A.</strong> 100</li><li><strong>B.</strong> 108</li><li><strong>C.</strong> 162</li><li><strong>D.</strong> 180</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260512173550.png" alt=""></p></div></details><hr><h2 id="q3-目前处理器市场中存在cpu和dsp两种类型处理器-分别用于不同场景-这两种处理器具有不同的体系结构-dsp采用-。" tabindex="-1">Q3. 目前处理器市场中存在CPU和DSP两种类型处理器，分别用于不同场景，这两种处理器具有不同的体系结构，DSP采用（ ）。 <a class="header-anchor" href="#q3-目前处理器市场中存在cpu和dsp两种类型处理器-分别用于不同场景-这两种处理器具有不同的体系结构-dsp采用-。" aria-label="Permalink to &quot;Q3. 目前处理器市场中存在CPU和DSP两种类型处理器，分别用于不同场景，这两种处理器具有不同的体系结构，DSP采用（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 冯.诺伊曼结构</li><li><strong>B.</strong> 哈佛结构</li><li><strong>C.</strong> FPGA结构</li><li><strong>D.</strong> 与GPU相同结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><h3 id="解析" tabindex="-1">解析 <a class="header-anchor" href="#解析" aria-label="Permalink to &quot;解析&quot;">​</a></h3><p><strong>DSP（数字信号处理器）</strong> 的典型体系结构是<strong>哈佛结构</strong>或<strong>改进的哈佛结构</strong>。</p><p>常见DSP（如TI TMS320系列）都采用<strong>哈佛结构</strong>或其变种，以实现指令流水线的高效率。</p><table tabindex="0"><thead><tr><th style="text-align:left;">选项</th><th style="text-align:left;">结构特点</th><th style="text-align:left;">是否DSP采用</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A. 冯·诺依曼结构</strong></td><td style="text-align:left;">指令和数据共用同一总线，顺序执行</td><td style="text-align:left;">❌ 传统CPU采用，DSP不用</td></tr><tr><td style="text-align:left;"><strong>B. 哈佛结构</strong></td><td style="text-align:left;">指令存储器和数据存储器<strong>分开</strong>，有独立总线，可<strong>并行读取</strong>指令和数据</td><td style="text-align:left;">✅ <strong>正确</strong>。DSP需要高速数据处理，哈佛结构支持指令预取和数据同时访问，提高吞吐量</td></tr><tr><td style="text-align:left;"><strong>C. FPGA结构</strong></td><td style="text-align:left;">现场可编程门阵列，是一种硬件可重构器件，不是处理器体系结构分类</td><td style="text-align:left;">❌ 不属于CPU/DSP的体系结构类型</td></tr><tr><td style="text-align:left;"><strong>D. 与GPU相同结构</strong></td><td style="text-align:left;">GPU采用流式多处理器+大量计算单元，与DSP不同</td><td style="text-align:left;">❌ DSP和GPU体系结构不同，DSP更侧重低功耗、确定性实时处理</td></tr></tbody></table></div></details><hr><h2 id="q4-以下关于串行总线的说法中-正确的是-。" tabindex="-1">Q4. 以下关于串行总线的说法中，正确的是（ ）。 <a class="header-anchor" href="#q4-以下关于串行总线的说法中-正确的是-。" aria-label="Permalink to &quot;Q4. 以下关于串行总线的说法中，正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 串行总线一般都是全双工总线，适宜于长距离传输数据</li><li><strong>B.</strong> 串行总线传输的波特率是总线初始化时预先定义好的，使用中不可改变</li><li><strong>C.</strong> 串行总线是按位（bit）传输数据的，其数据的正确性依赖于校验码纠正</li><li><strong>D.</strong> 串行总线的数据发送和接收是以软件查询方式工作</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><hr><h2 id="q10-嵌入式系统中采用中断方式实现输入输出的主要原因是-1-。在中断时-cpu断点信息一般保存到-2-中。" tabindex="-1">Q10. 嵌入式系统中采用中断方式实现输入输出的主要原因是 （1） 。在中断时，CPU断点信息一般保存到 （2） 中。 <a class="header-anchor" href="#q10-嵌入式系统中采用中断方式实现输入输出的主要原因是-1-。在中断时-cpu断点信息一般保存到-2-中。" aria-label="Permalink to &quot;Q10. 嵌入式系统中采用中断方式实现输入输出的主要原因是 （1） 。在中断时，CPU断点信息一般保存到 （2） 中。&quot;">​</a></h2><ul><li><strong>A.</strong> 通用寄存器</li><li><strong>B.</strong> 堆</li><li><strong>C.</strong> 栈</li><li><strong>D.</strong> I/O接口</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>根据嵌入式系统的基本原理，正确答案为：</p><ul><li><strong>(1) D. 能对突发事件做出快速响应</strong><br> 中断方式的主要优点是使CPU能够及时处理外部突发事件，提高系统的实时性。</li><li><strong>(2) 堆栈（栈）</strong><br> 中断发生时，CPU会把当前的断点信息（如程序计数器PC、状态寄存器等）自动压入堆栈保存，以便中断返回后能继续执行原程序。<br> 注：第二问的题目中未列出选项，但常见软考题中该空的标准答案是“堆栈”。如果选项中有“堆栈”，则选它；若有“内存”，则不精确，推荐选“堆栈”。</li></ul></div></details><hr><h2 id="q12-【51cto学堂-学员回忆版】通常-嵌入式中间件没有统一的架构风格-根据应用对象的不同可存在多种类型-比较常见的是消息中间件和分布式对象中间件。以下有关消息中间件的描述中-不正确的是-12-。" tabindex="-1">Q12. 【51CTO学堂-学员回忆版】通常，嵌入式中间件没有统一的架构风格，根据应用对象的不同可存在多种类型，比较常见的是消息中间件和分布式对象中间件。以下有关消息中间件的描述中，不正确的是(12)。 <a class="header-anchor" href="#q12-【51cto学堂-学员回忆版】通常-嵌入式中间件没有统一的架构风格-根据应用对象的不同可存在多种类型-比较常见的是消息中间件和分布式对象中间件。以下有关消息中间件的描述中-不正确的是-12-。" aria-label="Permalink to &quot;Q12. 【51CTO学堂-学员回忆版】通常，嵌入式中间件没有统一的架构风格，根据应用对象的不同可存在多种类型，比较常见的是消息中间件和分布式对象中间件。以下有关消息中间件的描述中，不正确的是(12)。&quot;">​</a></h2><ul><li><strong>A.</strong> 消息中间件是消息传输过程中保存消息的一种容器</li><li><strong>B.</strong> 消息中间件具有两个基本特点：来用异步处理模式、应用程序和应用程序调用关系为松耦合关系</li><li><strong>C.</strong> 消息中间件主要由一组对象来提供系统服务，对象间能够跨平台通信</li><li><strong>D.</strong> 消息中间件的消息传递服务模型有点对点模型和发布-订阅模型之分</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>解析</p><ul><li><strong>A</strong>：正确。消息中间件通常作为消息的暂存容器，支持存储转发。</li><li><strong>B</strong>：正确。消息中间件采用异步通信，且发送方和接收方松耦合。</li><li><strong>C</strong>：不正确。该描述更符合<strong>分布式对象中间件</strong>（如 CORBA、RMI、EJB）的特征——由一组对象提供跨平台服务。消息中间件的核心是<strong>消息队列和通道</strong>，而非“一组对象”。</li><li><strong>D</strong>：正确。点对点（队列）和发布-订阅（主题）是消息中间件的两种经典模型。</li></ul><p>所以，本题应选 <strong>C</strong>。</p></div></details><hr><h2 id="q13-内存按字节编址-地址从b0000h到dffffh的内存-共有-1-字节-若用存储容量为64k-4bit的存储器芯片构成该内存空间-至少需要-2-片。" tabindex="-1">Q13. 内存按字节编址，地址从B0000H到DFFFFH的内存，共有（1）字节，若用存储容量为64k* 4bit的存储器芯片构成该内存空间，至少需要（2）片。 <a class="header-anchor" href="#q13-内存按字节编址-地址从b0000h到dffffh的内存-共有-1-字节-若用存储容量为64k-4bit的存储器芯片构成该内存空间-至少需要-2-片。" aria-label="Permalink to &quot;Q13. 内存按字节编址，地址从B0000H到DFFFFH的内存，共有（1）字节，若用存储容量为64k* 4bit的存储器芯片构成该内存空间，至少需要（2）片。&quot;">​</a></h2><ul><li><strong>A.</strong> 4</li><li><strong>B.</strong> 5</li><li><strong>C.</strong> 6</li><li><strong>D.</strong> 8</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>解析</p><ol><li><p><strong>内存容量计算</strong><br> 地址范围：B0000H ～ DFFFFH<br> 总字节数 = DFFFFH - B0000H + 1 = 2FFFFH + 1 = 30000H<br> 转换为十进制：30000H = 3 × 16⁴ = 3 × 65536 = 196608 字节<br> 即 <strong>196608 B = 192 KB</strong>（因为 192 × 1024 = 196608）。</p></li><li><p><strong>芯片容量计算</strong><br> 芯片规格：64K × 4bit<br> 一片芯片的字节数 = (64 × 1024 × 4) / 8 = 64 × 1024 × 0.5 = 32 × 1024 = <strong>32 KB</strong>。</p></li><li><p><strong>所需片数</strong><br> 192 KB ÷ 32 KB = <strong>6 片</strong>。</p></li></ol><p>因此，至少需要 6 片该存储器芯片。</p></div></details><hr><h2 id="q29-某硬盘有4个记录面-每面有1000个磁道-每个磁道有200个扇区-每个扇区可存储512字节。该硬盘的格式化容量是多少-。" tabindex="-1">Q29. 某硬盘有4个记录面，每面有1000个磁道，每个磁道有200个扇区，每个扇区可存储512字节。该硬盘的格式化容量是多少（ ）。 <a class="header-anchor" href="#q29-某硬盘有4个记录面-每面有1000个磁道-每个磁道有200个扇区-每个扇区可存储512字节。该硬盘的格式化容量是多少-。" aria-label="Permalink to &quot;Q29. 某硬盘有4个记录面，每面有1000个磁道，每个磁道有200个扇区，每个扇区可存储512字节。该硬盘的格式化容量是多少（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 400MB</li><li><strong>B.</strong> 800MB</li><li><strong>C.</strong> 400GB</li><li><strong>D.</strong> 800GB</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p><p>解析：</p><p>容量计算：</p><ul><li>记录面数：4</li><li>每面磁道数：1000</li><li>每磁道扇区数：200</li><li>每扇区字节数：512</li></ul><p>总字节数 = 4 × 1000 × 200 × 512<br> = 4 × 1000 × 102400<br> = 4 × 102,400,000<br> = 409,600,000 字节</p><p>换算为 MB（按 1 MB = 10⁶ 字节，硬盘常用标称）：<br> 409,600,000 ÷ 1,000,000 = 409.6 MB ≈ <strong>400 MB</strong>（选项中最接近）</p><p>若按二进制 1 MB = 2²⁰ = 1,048,576 字节，则约为 390.6 MB，仍接近 400 MB。<br> 选项 B、C、D 数值过大，因此 <strong>A 正确</strong>。</p></div></details><hr><h2 id="q30-在计算机系统中-硬盘的存取时间主要由哪些部分组成-。" tabindex="-1">Q30. 在计算机系统中，硬盘的存取时间主要由哪些部分组成（ ）。 <a class="header-anchor" href="#q30-在计算机系统中-硬盘的存取时间主要由哪些部分组成-。" aria-label="Permalink to &quot;Q30. 在计算机系统中，硬盘的存取时间主要由哪些部分组成（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 寻道时间、等待时间、读/写时间</li><li><strong>B.</strong> 寻道时间、等待时间</li><li><strong>C.</strong> 寻道时间、读/写时间</li><li><strong>D.</strong> 等待时间、读/写时间</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><p>解析</p><ul><li><strong>寻道时间</strong>：磁头移动到目标磁道所需的时间。</li><li><strong>等待时间</strong>（旋转延迟）：目标扇区旋转到磁头下方所需的时间。</li><li><strong>读/写时间</strong>：数据实际传输的时间。</li></ul><p>三者之和即为硬盘的存取时间。因此 A 完整准确。</p><hr><h2 id="q33-下列哪个不属于串行总线-。" tabindex="-1">Q33. 下列哪个不属于串行总线（ ）。 <a class="header-anchor" href="#q33-下列哪个不属于串行总线-。" aria-label="Permalink to &quot;Q33. 下列哪个不属于串行总线（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> USB</li><li><strong>B.</strong> SATA</li><li><strong>C.</strong> PCI</li><li><strong>D.</strong> RapidIO</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>正确答案是 <strong>C. PCI</strong>。</p><p>解析</p><ul><li><strong>A. USB</strong>：通用串行总线，标准串行总线。</li><li><strong>B. SATA</strong>：串行高级技术附件，串行总线。</li><li><strong>C. PCI</strong>：传统外设组件互连总线，<strong>并行总线</strong>（非串行）。PCIe（PCI Express）才是串行，但此处 PCI 指早期并行版本。</li><li><strong>D. RapidIO</strong>：高性能嵌入式串行总线。</li></ul><p><strong>方法技巧</strong>：</p><p>判断一种总线是串行还是并行，关键看数据线是否多根并行传输。串行总线只有一根（或一对差分线）逐位传输，常见如 USB、SATA、PCIe、RapidIO、I²C、SPI 等；并行总线有多根数据线同时传输多位，如传统 PCI、ISA、PATA（IDE）等。<br> 考试中若出现“PCI”未说明“PCIe”，通常指并行 PCI，故不属于串行总线。</p></div></details><hr><h2 id="q37-cache存储器设计的理论依据是-。" tabindex="-1">Q37. Cache存储器设计的理论依据是（ ）。 <a class="header-anchor" href="#q37-cache存储器设计的理论依据是-。" aria-label="Permalink to &quot;Q37. Cache存储器设计的理论依据是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 程序的局部性原理</li><li><strong>B.</strong> 程序的并行性原理</li><li><strong>C.</strong> 存储器的分级原理</li><li><strong>D.</strong> 程序的顺序性原理</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p><p>解析</p><ul><li><strong>局部性原理</strong>包括时间局部性（刚访问的数据可能再次访问）和空间局部性（附近的数据可能被访问），这是 Cache 能够显著提高命中率的理论基础。</li><li><strong>B</strong> 并行性原理用于多核、流水线等，与 Cache 设计无关。</li><li><strong>C</strong> 存储分级是体系结构的事实，但 Cache 的存在依据是局部性，而非分级本身。</li><li><strong>D</strong> 顺序性原理没有此说法。</li></ul><p>因此，Cache 设计的核心理论依据是 <strong>程序的局部性原理</strong>。</p></div></details><hr><h2 id="q44-关于现代计算机处理器的特点-下列说法正确的是-。" tabindex="-1">Q44. 关于现代计算机处理器的特点，下列说法正确的是（ ）。 <a class="header-anchor" href="#q44-关于现代计算机处理器的特点-下列说法正确的是-。" aria-label="Permalink to &quot;Q44. 关于现代计算机处理器的特点，下列说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 控制单元和运算单元必须分开设计</li><li><strong>B.</strong> 控制单元和运算单元被集成为一体</li><li><strong>C.</strong> 处理器只包含控制单元和运算单元两部分</li><li><strong>D.</strong> 处理器不包含控制单元</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>解析</p><ul><li><strong>A</strong> ❌：现代处理器中控制单元和运算单元集成在同一芯片内，并非必须分开。</li><li><strong>B</strong> ✅：正确，CPU 将控制单元和运算单元（ALU）等集成在一起。</li><li><strong>C</strong> ❌：不完整，处理器还包含寄存器、缓存等部件。</li><li><strong>D</strong> ❌：处理器必须包含控制单元，否则无法取指译码执行。</li></ul><p>因此，B 为正确选项。</p></div></details><hr><h2 id="q1-某航空公司机票销售系统有n个售票点" tabindex="-1">Q1. 某航空公司机票销售系统有n个售票点， <a class="header-anchor" href="#q1-某航空公司机票销售系统有n个售票点" aria-label="Permalink to &quot;Q1. 某航空公司机票销售系统有n个售票点，&quot;">​</a></h2><p>该系统为每个售票点创建一个进程Pi(i=1，2，…，n)管理机票销售。假设Tj(j=1，2，…，m)单元存放某日某航班的机票剩余票数，Temp为Pi 进程的临时工作单元，x 为某用户的订票张数。</p><p>初始化时系统应将信号量S赋值为(请作答此空)。Pi进程的工作流程如下图所示，若用P操作和V操作实现进程间的同步与互斥，则图中空(a)、空(b)和空(c)处应分别填入(2)。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260513152010.png" alt="image.png"></p><ul><li><strong>A.</strong> 0</li><li><strong>B.</strong> 1</li><li><strong>C.</strong> 2</li><li><strong>D.</strong> 3</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>根据题目描述和流程图分析，这是一个典型的<strong>多进程互斥访问共享资源</strong>（机票剩余票数 <code>Tj</code>）的问题。</p><p>第一问：信号量 <code>S</code> 的初始值</p><ul><li>多个售票点进程 <code>Pi</code> 需要互斥地访问共享变量 <code>Tj</code>（剩余票数），以避免数据不一致。</li><li>因此，需要一个互斥信号量 <code>S</code>，初始值应为 <strong>1</strong>（表示资源可用，只有一个进程能进入临界区）。</li></ul><p><strong>答案：<code>1</code></strong></p><p>第二问：图中 <code>(a)</code>、<code>(b)</code>、<code>(c)</code> 处应填入的操作</p><ul><li><strong><code>(a)</code></strong>：在访问共享变量 <code>Tj</code> 之前，必须进行互斥，所以应该执行 <strong><code>P(S)</code></strong>（申请进入临界区）。</li><li><strong><code>(b)</code></strong>：在成功出票（更新 <code>Tj</code>）后，需要释放临界区，所以应该执行 <strong><code>V(S)</code></strong>。</li><li><strong><code>(c)</code></strong>：当余票不足时，也需要释放临界区（因为已经执行了 <code>P(S)</code>，如果不释放会导致死锁），所以也应该执行 <strong><code>V(S)</code></strong>。</li></ul><p>因此，三个空应分别填入：<strong><code>P(S)</code>、<code>V(S)</code>、<code>V(S)</code></strong>。</p><p>完整答案</p><table tabindex="0"><thead><tr><th style="text-align:left;">空位</th><th style="text-align:left;">应填内容</th></tr></thead><tbody><tr><td style="text-align:left;">第一空</td><td style="text-align:left;"><strong>1</strong></td></tr><tr><td style="text-align:left;">第二空</td><td style="text-align:left;"><strong>(a) P(S), (b) V(S), (c) V(S)</strong></td></tr></tbody></table><p>注意：如果题目提供的选项中有不同的顺序（例如 <code>P(S)</code> 和 <code>V(S)</code> 的写法不同，或信号量名称不同），请以标准 PV 操作符号为准。但核心逻辑不变：进入临界区前 <code>P</code>，退出临界区时 <code>V</code>（两个退出路径都要 <code>V</code>）。</p></div></details><hr><h2 id="q2-假设系统采用段式存储管理方法-进程p的段表如下所示。逻辑地址-请作答此空-不能转换为对应的物理地址-不能转换为对应的物理地址的原因是进行-。" tabindex="-1">Q2. 假设系统采用段式存储管理方法，进程P的段表如下所示。逻辑地址（请作答此空）不能转换为对应的物理地址；不能转换为对应的物理地址的原因是进行（）。 <a class="header-anchor" href="#q2-假设系统采用段式存储管理方法-进程p的段表如下所示。逻辑地址-请作答此空-不能转换为对应的物理地址-不能转换为对应的物理地址的原因是进行-。" aria-label="Permalink to &quot;Q2. 假设系统采用段式存储管理方法，进程P的段表如下所示。逻辑地址（请作答此空）不能转换为对应的物理地址；不能转换为对应的物理地址的原因是进行（）。&quot;">​</a></h2><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260513152907.png" alt="image.png"></p><ul><li><strong>A.</strong> (0，790)和(2，88)</li><li><strong>B.</strong> (1，30)和(3，290)</li><li><strong>C.</strong> (2，88)和(4，98)</li><li><strong>D.</strong> (0，810)和(4，120)</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>段式存储：逻辑地址 (段号, 段内偏移) 能否转换，要看偏移量是否超过该段的段长。</p><p>▎ · 段0：基址1100，段长800 → 偏移810 &gt; 800 ❌ 越界<br> ▎ · 段4：基址2000，段长100 → 偏移120&gt; 100 ❌ 越界</p><p>答案选择：D</p></div></details>',105)])])}const h=l(a,[["render",n]]);export{p as __pageData,h as default};
